private static void bfs(char[][] grid, int x, int y, Set<Integer> depositedPlots) {
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{x, y});
    depositedPlots.add(x * grid.length + y);
    while (!queue.isEmpty()) {
        int[] curr = queue.remove();
        int currX = curr[0];
        int currY = curr[1];
        if (grid[currX][currY] == '@') {
