        int end = n - 1;
        double minCost = Double.MAX_VALUE;
        double minAdjCost = Double.MAX_VALUE;
        double minDistance = Double.MAX_VALUE;
        double minAdjDistance = Double.MAX_VALUE;
        for (int j = 0; j < n; j++) {
