public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
  // Initialize a set to store visited n-tersections
  Set<Integer> visited = new HashSet<>();

  // Initialize a queue for Breadth-First Search
  Queue<Integer> queue = new LinkedList<>();

  // Add the starting n-tersection to the queue and visited set
  queue.add(start);
  visited.add(start);

  // Loop until the queue is empty
  while (!queue.isEmpty()) {
    // Dequeue a n-tersection from the queue
    int current = queue.remove();

    // If the current n-tersection is the ending n-tersection, return "can be travelled"
    if (current == end) {
      return "can be travelled";
    }

    // Get all reachable n-tersections from the current n-tersection
    int[] reachable = paths[current];

    // Loop through all reachable n-tersections
    for (int i = 0; i < reachable.length; i++) {
      // If the n-tersection is not already visited, add it to the queue and visited set
      if (!visited.contains(reachable[i])) {
        queue.add(reachable[i]);
        visited.add(reachable[i]);
      }
    }
  }

  // If the ending n-tersection was not found, return "cannot be travelled"
  return "cannot be travelled";
}
