  // returns the minimum cost to climb n stairs, being at either i-th or 
  // (i-1)-th step
  public int minCost(int n, int[] cost) {

    if (cost.length == 1) {
      return cost[0];
    } else if (cost.length == 2) {
      return cost[0] < cost[1] ? cost[0]
                               : cost[1];
    } else {
      // calculate the minimum cost for level
