import java.util.Map;
import java.util.Set;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        // HashMap to keep track of the counts of each element in the array
        Map<Integer, Integer> elementCounts = new HashMap<>();

        // Initialize the HashMap with the elements of the array as keys and their counts as values
        for (int i = 0; i < A.length; i++) {
            if (elementCounts.containsKey(A[i])) {
                elementCounts.put(A[i], elementCounts.get(A[i]) + 1);
            } else {
                elementCounts.put(A[i], 1);
            }
