        // Set to keep track of the unique permutations of the array
        Set<int[]> permutations = new HashSet<>();

        // Recursive function to generate and check permutations
        permute(A, 0, permutations, new int[A.length], elementCounts);

        // Return the size of the set of unique permutations
        return permutations.size();
    }

